insert into public.topics (module_id, slug, title, summary, position, published) select id, 'forms-and-input-elements', 'Forms and Input Elements', 'How forms collect user input and send it to a server.', 0, true from public.modules where level_id = 1 and title = 'HTML Essentials' on conflict (slug) do nothing;
insert into public.lessons (topic_id, objectives, explanation, code_lang, code, code_explanation, activity, mistakes, recap, version) select id, '["Explain forms and input elements in your own words.","Recognise and apply: every input needs a label so users and screen readers know its purpose.","Recognise and apply: the name attribute decides what the server receives for each field.","Complete the practical activity and check it against the success criteria."]'::jsonb, '["This lesson covers forms and input elements: how forms collect user input and send it to a server. It is written for a complete beginner, so every idea is introduced in plain language before any code appears.","The first key idea is that every input needs a label so users and screen readers know its purpose. In practice that means a learner should be able to recognise it in a real page or project, not only repeat a definition. Work through the example below slowly and predict what each line does before reading its explanation.","The second key idea is that the name attribute decides what the server receives for each field. This is the idea most beginners get wrong, so the common-mistakes section below shows the wrong version next to the corrected version.","Finally, remember that how forms and input elements fits into real web development work. A professional developer does not memorise every detail — they understand the idea, practise it on a small real task, and check their work. That is exactly what the practical activity at the end of this lesson asks you to do."]'::jsonb, 'html', '<form action="/register" method="post">
